int solve(int i, vector<int>& nums, int Xor) {
    static const vector<int>* cachedNums = nullptr;
    static unordered_map<long long, int> memo;
    if (cachedNums != &nums) {
        memo.clear();
        cachedNums = &nums;
    }
    long long key = ( (static_cast<long long>(i) << 32) | (static_cast<unsigned int>(Xor)) );
    auto it = memo.find(key);
    if (it != memo.end()) return it->second;
    if (i == static_cast<int>(nums.size())) {
        memo[key] = Xor;
        return Xor;
    }
    int include = solve(i + 1, nums, nums[i] ^ Xor);
    int exclude = solve(i + 1, nums, Xor);
    int res = include + exclude;
    memo[key] = res;
    return res;
}

